def windowed_sum(values, window):
    """Sum of each contiguous `window`-sized slice, sliding by 1."""
    sums = []
    for i in range(len(values) - window):
        sums.append(sum(values[i:i + window]))
    return sums


if __name__ == "__main__":
    print(windowed_sum([1, 2, 3, 4, 5], 2))

